from .pymosaic import (getVersionAPI, closeMosaic, openTestSession, closeTestSession, storeZipArchive, setOptions,
                       loadSid, initializeTestManager, isSimulatorReady, loadScenario, getStatus, startScenario,
                       getTestResult, parseTestResult, addCounters, getCounters, removeCounters, logCountersToFile,
                       getLogCounters, stopTestManager, queryWaitingSemaphores, unlockSemaphores, getBugreport,
                       setGlobalVariable, getCellStatus, getHarnessStats, getScenarioLogger, getScenarioStatus,
                       initLocalAirMosaic, closeLocalAirMosaic, getGroups, startGroup, resumeGroup, pauseGroup,
                       setTesterModeRest, socketAddress, socketPort, URLOPEN_TIMEOUT)

# Default configuration:
socketAddress = socketAddress
socketPort = socketPort
URLOPEN_TIMEOUT = URLOPEN_TIMEOUT


def get_restapi_version(host=socketAddress, port=socketPort):
    restapi_version_result = getVersionAPI(host=host, port=port)
    restapi_version = restapi_version_result.get('version', '')
    return restapi_version


class pymosaic(object):
    
    restVer = ''

    @staticmethod
    def closeMosaic(host=socketAddress, port=socketPort):
        """Shutdown Airmosaic

        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
         or *failed* and *error* is the failure cause

        """
        return closeMosaic(host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def openTestSession(host=socketAddress, port=socketPort):
        """Open a new test session.

        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error},
        :where *result* can be *success* or *failed* and *error* is the failure cause

        """
        pymosaic.restVer = get_restapi_version(host=host, port=port)
        return openTestSession(host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def closeTestSession(session_id, host=socketAddress, port=socketPort):
        """Close a test session

        :param sessionId: session_id of the test session to be closed
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
         or *failed* and *error* is the failure cause

        """
        return closeTestSession(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def storeZipArchive(session_id, inzip, outzip, host=socketAddress, port=socketPort):
        """ Load zip file with Airmosaic cfg and scenario files and
        store it as *outzip*

        :param sessionId: session_id of the current test session
        :param inzip: path to a zip compressed archive containing all the needed
        Airmosaic cfg and scenario files
        :param outzip: name to be given to the *inzip* file once saved in
        Airmosaic temporary folder (e.g.: 'cfg.zip')
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and *error* is the failure cause

        """
        return storeZipArchive(session_id=session_id, inzip=inzip, outzip=outzip, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def setOptions(session_id, options, host=socketAddress, port=socketPort):
        """Set Airmosaic options

        :param sessionId: session_id of the current test session
        :param options: dictionary with *parameter*/*value* pairs of options to be
        set (e.g.: {'enableAMM':True})
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and *error* is the failure cause

        """
        return setOptions(session_id=session_id, options=options, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def loadSid(session_id, sid, host=socketAddress, port=socketPort):
        """Load given sid file

        :param sessionId: session_id of the current test session
        :param sid: name of the sid file to be loaded. It must have already been
        sent to Airmosaic through the storeZipArchive method
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and *error* is the failure cause

        """
        return loadSid(session_id=session_id, sid=sid, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def initializeTestManager(session_id, host=socketAddress, port=socketPort):
        """Connect to TSTM

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and *error* is the failure cause

        """
        return initializeTestManager(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def isSimulatorReady(session_id, host=socketAddress, port=socketPort):
        """Check if the simulator is ready to run the scenario

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error, 'ready':ready, 'readyInfo':''},
        where *result* can be *success* or *failed*,
                *error* is the failure cause and *ready* is set to True
                if the simulator is ready, otherwise it is set to False

        """
        return isSimulatorReady(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def loadScenario(session_id, sce, host=socketAddress, port=socketPort):
        """Load given scenario

        :param sessionId: session_id of the current test session
        :param sce: name of the sce file to be loaded. It must have already been
        sent to Airmosaic through the storeZipArchive method
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and *error* is the failure cause

        """
        return loadScenario(session_id=session_id, sce=sce, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def getStatus(session_id, host=socketAddress, port=socketPort):
        """Get scenario execution status

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error, 'status':status},
        where *result* can be *success* or *failed*,
                *error* is the failure cause and *status* can be set to:
                NONE, SIMINIT_AVAILABLE_INVALID, SIMINIT_AVAILABLE,
                RUNNING_SIMINIT, RUNNING_SIMINIT_SCEAVAIL, SIMINIT_COMPLETED,
                SCENARIO_AVAILABLE, SCENARIO_RUNNABLE,
                RUNNING_SCENARIO, SCENARIO_COMPLETED, ABNORMAL_FAIL, SID_OPENING

        """
        return getStatus(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def startScenario(session_id, host=socketAddress, port=socketPort):
        """Start scenario execution

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and *error* is the failure cause

        """
        return startScenario(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def getTestResult(session_id, host=socketAddress, port=socketPort, **kwargs):
        """Get final test result in XML format, after scenario execution end

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error, 'testResult':testResult},
        where *result* can be *success* or *failed*, *error*
                is the failure cause and *testResult* is an XML string containing
                a summary of the test execution result.

        """
        return getTestResult(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer, **kwargs)

    @staticmethod
    def parseTestResult(session_id, testResult, host=socketAddress, port=socketPort):
        """Parse output of getTestResult XML format

        :param testResult: json input as result of getTestResult function
        :return: {'result':result, 'error':error, 'testResult':testResult},
        where *result* can be *success* or *failed*, *error*
                is the failure cause and *testResult* is an XML string containing
                a summary of the test execution result.

        """
        return parseTestResult(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def addCounters(session_id, counters, host=socketAddress, port=socketPort):
        """Register counters to be collected during test execution

        :param sessionId: session_id of the current test session
        :param counters: a list of dictionaries each identifying a specific
        counter to be collected:
                        [{'category':category, 'instance':instance, 'name':name},...]
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error, 'addedCounters':addedCounters},
        where *result* can be *success* or *failed*,
                *error* is the failure cause and *addedCounters* is the
                list of actually added counters in the same format of the
                *counters* parameter.

        """
        return addCounters(session_id=session_id, _counters=counters, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def getCounters(session_id, host=socketAddress, port=socketPort):
        """Get the current value of the registered counters

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error, 'counters':counters},
        where *result* can be *success* or *failed*,
                *error* is the failure cause and *counters* is the list of
                all the registered counters, each with its current value:
                [{'category':category, 'instance':instance, 'name':name, 'value':value},...]

        """
        return getCounters(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def removeCounters(session_id, counters, host=socketAddress, port=socketPort):
        """Unregister previously registered counters

        :param sessionId: session_id of the current test session
        :param counters: a list of dictionaries each identifying a
        specific counter to be unregistered:
                        [{'category':category, 'instance':instance, 'name':name},...]
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error, 'removedCounters':removedCounters},
        where *result* can be *success* or *failed*,
                *error* is the failure cause and *removedCounters* is the list
                of counters that were actually removed

        """
        return removeCounters(session_id=session_id, lcounters=counters, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def logCountersToFile(session_id,
                          counters,
                          host=socketAddress,
                          port=socketPort,
                          enabled=True,
                          frequency=1,
                          aggregate=True,
                          lastLogOnly=False):
        """Register counters to be logged to csv file

        :param sessionId: session_id of the current test session
        :param counters: list of counters to be logged to csv files.
        See Airmosaic Harness interface documentation for the
                        description of the format of this parameter
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :param enabled: whether counters logging to csv is enabled or
        not (defaults to True)
        :param frequency: counters logging frequency, in seconds (defaults to 1)
        :param aggregate: whether to generate an aggregated csv for all the
        instances of the same category or not (defaults to True)
        :param lastLogOnly: whether to log only the last value of each counter
        or all of them (defaults to False)
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and *error* is the failure cause

        """
        return logCountersToFile(session_id=session_id, counters=counters, enabled=enabled,
                                 frequency=frequency, aggregate=aggregate, lastLogOnly=lastLogOnly,
                                 host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def getLogCounters(session_id, host=socketAddress, port=socketPort):
        """Get a zip compressed archive containing the csv files
        where the counters were saved

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error, 'countersCsvFile':countersCsvFile},
        where *result* can be *success* or *failed*,
                *error* is the failure cause and *countersCsvFile* is
                the base64 encoded zip file content

        """
        return getLogCounters(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def stopTestManager(session_id, host=socketAddress, port=socketPort):
        """Stop scenario execution

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and *error* is the failure cause

        """
        return stopTestManager(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def queryWaitingSemaphores(session_id, host=socketAddress, port=socketPort):
        """Get the list of semaphores currently in waiting status

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error, 'waitingList':waitingList},
        where *result* can be *success* or *failed*,
                *error* is the failure cause and *waitingList* is the list of
                semaphores in waiting status, each with its id,
                in this format:
                [{'group':groupName, 'scenarioSession':sessionName,
                'type':begin/end, 'id':id},...]

        """
        return queryWaitingSemaphores(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def unlockSemaphores(session_id,
                         unlockIdList,
                         host=socketAddress,
                         port=socketPort):
        """Unlock given semaphores

        :param sessionId: session_id of the current test session
        :param unlockIdList: list of ids of the semaphores to be unlocked:
        [{'id':1},{'id':2},...]
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result*
        can be *success* or *failed* and *error* is the failure cause

        """
        return unlockSemaphores(session_id=session_id, unlockIdList=unlockIdList, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def getBugreport(session_id, host=socketAddress, port=socketPort, **kwargs):
        """Generate and get the bugreport archive

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :param filename(optional): If present, bugreport is saved on the filename file
        :return: {'result':result, 'error':error, 'bugreportFile':bugreportFile},
        where *result* can be *success* or *failed*,
        *error* is the failure cause and *bugreportFile* is the base64 encoded bugreport

        """
        return getBugreport(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer, **kwargs)

    @staticmethod
    def setGlobalVariable(session_id,
                          name,
                          value,
                          host=socketAddress,
                          port=socketPort):
        """Change the value of a global variable

        :param sessionId: session_id of the current test session
        :param name: variable name
        :param value: variable value
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and
                *error* is the failure cause

        """
        return setGlobalVariable(session_id=session_id, name=name, value=value, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def getCellStatus(session_id, host=socketAddress, port=socketPort):
        """Returns the current status of a cell connected to Airmosaic

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {'result':result, 'error':error,cellStatus:
        [{"id":btsId,"status":status}.....]},
        where *result* can be *success* or *failed* and
                *error* is the failure cause

        """
        return getCellStatus(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def getHarnessStats(host=socketAddress, port=socketPort):
        """Get session activity statistics

        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: { result: "sucess|failed",   error:"", activeSessionStats: []},
        where *result* can be *success* or *failed* and *error* is the failure cause
        and activeSessionStats has structure:
            {sessionId: "6016d604-4c76-4ddd-99f0-c6940c25b525",
            taskList: [ {date: "Fri Sep 16 14:33:21 CEST 2016",
            result: "sucess|failed",error: ""}...]}
        """
        return getHarnessStats(host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def getScenarioLogger(session_id,
                          host=socketAddress,
                          port=socketPort,
                          startId="",
                          endId=""):
        """return a copy of the scenario logger file
        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :param startId: starting line number in the scenario logger to be reported,
         if obmitted all the line from the beginning are collected
        :param endId: finish line number in the scenario logger to be reported,
        if obmitted all the line untill the end are collected
        :return: {result: "sucess|failed", error:"", logRecords: [.]},\n
                where *result* can be *success* or *failed*,\n
                *error* is the failure cause, \n
                *logreport* is an array of structure defined as:\n
                {'recordId': record, 'datetime': datetime,
                'instance': instance, 'messageLevel': messageLevel,
                'category': category, 'message': message, 'group': group}

        |

        :example: getScenarioLogger("xyz")
        :example output:\n
            {\n
                result: "sucess|failed"\n
                error:""\n
                logRecords: [\n
                        {\n
                            recordId: 1,\n
                            datetime: 13918,\n
                            instance: "New Subscriber",\n
                            messageLevel: "ERROR",\n
                            category: "Subscribers",\n
                            message: "CLIPdpActivate: Invalid procedure (Cell=0)",\n
                            group: "sg1"\n
                        },\n
                        ...\n
                        ]\n
            }\n

        """
        return getScenarioLogger(session_id=session_id, host=host, port=port,
                                 startId=startId, endId=endId, restVer=pymosaic.restVer)

    @staticmethod
    def getScenarioStatus(session_id, host=socketAddress, port=socketPort):
        """Get scenario information about status, while scenario is
        in RUNNING_SCENARIO the result give detailed info about each step in scenario

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :return: {result: "sucess|failed", error:"",
        scenarioStatus: { "groups": [ { sessions: [{ name: name,
        traces: [{ tests: [ { type: type, status: status }], id: id }]}]}]}

        |

        :example: getScenarioStatus("xyz")
        :example output:\n
                {    result: "sucess|failed", \n
                    error:"",\n
                    scenarioStatus: {\n
                        "groups": [{\n
                                sessions: [{\n
                                    name: "New session 26",\n
                                    traces: [{\n
                                        tests: [{type: "PDP Activate", status: "None" },...],\n
                                        id: 0\n
                                },...]\n
                        }],...\n
                    }]\n
            }\n

        """
        return getScenarioStatus(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def initLocalAirMosaic(path="", airmosaic_port=8090, rat="LTE"):
        """
        start Harness session listening on thye given port
        If another instance is running it will be close first

        : param port:   harness tcp port
        : return:       the subprocess.Popen object created
        """
        return initLocalAirMosaic(path=path, airmosaic_port=airmosaic_port, rat=rat)

    @staticmethod
    def closeLocalAirMosaic(airmosaic_port=8090):
        """ close Harness session on the given port

        : param port:   harness tcp port
        : return:       always return 0 if no problem occurs atherwise retunn error info
        """
        return closeLocalAirMosaic(airmosaic_port=airmosaic_port, restVer=pymosaic.restVer)

    @staticmethod
    def getGroups(session_id, host=socketAddress, port=socketPort):
        """Retrieve groups' names from scenario

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening

        :return: {'result':'success' | 'failed', 'error': failure_cause}

        :example: getGroups("86e66923-8b1e-4b01-91de-044625dcbe32")

        :sample output: {'result': 'success', 'error': ''}
        """
        return getGroups(session_id=session_id, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def startGroup(session_id, groupName, host=socketAddress, port=socketPort):
        """Start scenario with all the available groups on pause but groupName,
        which is running

        :param sessionId: session_id of the current test session
        :param groupName: name of a scenario's group
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening

        :return: {'result':'success' | 'failed', 'error': failure_cause}

        :example: startGroup("86e66923-8b1e-4b01-91de-044625dcbe32", "Group1")

        :sample output: {'result': 'success', 'error': ''}
        """
        return startGroup(session_id=session_id, groupName=groupName, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def resumeGroup(session_id, groupName, host=socketAddress, port=socketPort):
        """Change the group groupName status to running

        :param sessionId: session_id of the current test session
        :param groupName: name of a scenario's group
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening

        :return: {'result':'success' | 'failed', 'error': failure_cause}

        :example: resumeGroup("86e66923-8b1e-4b01-91de-044625dcbe32", "Group1")

        :sample output: {'result': 'success', 'error': ''}
        """
        return resumeGroup(session_id=session_id, groupName=groupName, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def pauseGroup(session_id, groupName, host=socketAddress, port=socketPort):
        """Pause the groupName group execution

        :param sessionId: session_id of the current test session
        :param groupName: name of a scenario's group
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :
        :return: {'result':'success' | 'failed', 'error': failure_cause}

        :example: pauseGroup("86e66923-8b1e-4b01-91de-044625dcbe32", "Group1")

        :sample output: {'result': 'success', 'error': ''}
        """
        return pauseGroup(session_id=session_id, groupName=groupName, host=host, port=port, restVer=pymosaic.restVer)

    @staticmethod
    def setTesterMode(session_id, ppucontrol, cellcontrol, host=socketAddress, port=socketPort):
        """Set Airmosaic to work in tester mode

        :param sessionId: session_id of the current test session
        :param host: IP address at which Airmosaic is listening
        :param port: port at which Airmosaic is listening
        :param ppucontrol: disable the ppu check to let the test start
        :param cellcontrol: disable the cell sync check to let the test start
        :return: {'result':result, 'error':error}, where *result* can be *success*
        or *failed* and
                *error* is the failure cause

        """
        return setTesterModeRest(session_id=session_id, ppucontrol=ppucontrol, cellcontrol=cellcontrol,
                                 host=host, port=port, restVer=pymosaic.restVer)
